/**
 * Builds the one script Qoder's windows load: dist/smartrtl-qoder.js.
 *
 * The script runs in the page as a plain script, so the shared pieces are inlined here, not
 * copied by hand:
 *
 *   @smartrtl/core  the rule      - which direction does this text belong to?
 *   @smartrtl/dom   the engine    - when to ask, and what to do with the answer
 *   src/adapter.js  the adapter   - the parts that are only true of Qoder
 *
 * Both packages are UMD files: given a fresh local `module`, each hands back its exports.
 * Everything stays inside one named function, so nothing of ours reaches the page's globals
 * except window.__smartRtlQoder - and the adapter can hand that same function, whole, to a
 * chat window that has been moved out of the workbench.
 *
 *   node build/bundle.js
 */
const crypto = require("node:crypto");
const fs = require("node:fs");
const path = require("node:path");

const root = path.resolve(__dirname, "..");
const core = fs.readFileSync(path.resolve(root, "../../packages/core/src/direction.js"), "utf8");
const dom = fs.readFileSync(path.resolve(root, "../../packages/dom/src/engine.js"), "utf8");
const adapter = fs.readFileSync(path.join(root, "src/adapter.js"), "utf8");
const outPath = path.join(root, "dist/smartrtl-qoder.js");

const BEGIN = "/* ==== smart-rtl-direction patch BEGIN ==== */";
const END = "/* ==== smart-rtl-direction patch END ==== */";
const FROZEN = "8b72c365e1d7ec8609e7207fd48b3760b1834ee276892a45515cb2faaed34998";

// The rule ships only as frozen; the adapter must go through the engine, and the engine
// through the rule. If any of that is lost, the build fails here.
if (crypto.createHash("sha256").update(core.replace(/\r\n/g, "\n")).digest("hex") !== FROZEN) throw new Error("the frozen formula's checksum differs");
if (!adapter.includes("SmartRTLDom.start(SmartRTL")) throw new Error("the adapter does not hand the shared rule to the shared engine");
if (!dom.includes("rule.openingLetters")) throw new Error("the engine does not use the shared rule");

const out = [
  BEGIN,
  "/* generated by build/bundle.js - edit src/adapter.js instead */",
  ";(function smartRtlQoder() {",
  '  "use strict";',
  "  var module = { exports: {} };",
  core.trim(),
  "  var SmartRTL = module.exports;",
  "  module = { exports: {} };",
  dom.trim(),
  "  var SmartRTLDom = module.exports;",
  adapter.replace(BEGIN, "").replace(END, "").trim(),
  "})();",
  END,
  "",
].join("\n");

new Function(out); // parse check: a broken script must never reach Qoder
fs.mkdirSync(path.dirname(outPath), { recursive: true });
fs.writeFileSync(outPath, out, "utf8");
console.log(`dist/smartrtl-qoder.js ${out.length} bytes`);
